import{Ot as e,ct as t,it as n,lt as r,n as i,st as a,ut as o,wt as s}from"./chunks/framework.eUj94whv.js";var c=JSON.parse(`{"title":"形状与边界","description":"","frontmatter":{},"headers":[],"relativePath":"design/shape.md","filePath":"design/shape.md","lastUpdated":1791656162000}`),l={name:`design/shape.md`};function u(i,c,l,u,d,f){let p=e(`XhTokenTable`);return s(),a(`div`,null,[c[0]||=n(`h1`,{id:`形状与边界`,tabindex:`-1`},[r(`形状与边界 `),n(`a`,{class:`header-anchor`,href:`#形状与边界`,"aria-label":`Permalink to “形状与边界”`},`​`)],-1),c[1]||=n(`p`,null,`圆角与边线是最容易长出第二套规则的地方——一个组件 6px、另一个 5px，看着都"差不多"。这里的规则是：圆角只有一条语义阶梯，边界只由描边承担，两者都由门禁逐条扫。`,-1),c[2]||=n(`h2`,{id:`圆角阶梯`,tabindex:`-1`},[r(`圆角阶梯 `),n(`a`,{class:`header-anchor`,href:`#圆角阶梯`,"aria-label":`Permalink to “圆角阶梯”`},`​`)],-1),o(p,{kind:`radius`,names:[`--xh-shape-inset`,`--xh-shape-control`,`--xh-shape-surface`,`--xh-shape-overlay`,`--xh-shape-circle`,`--xh-shape-pill`],notes:{"--xh-shape-inset":`2px · 嵌在控件里的内层：勾选方框、页内列表的候选行（Listbox、Tree）、字段内的清空钮、表格行选择框、色块`,"--xh-shape-control":`2px · 控件本体：Button、Input、Select trigger、Toggle、kbd、tooltip、Tabs / Steps trigger、单选组 segmented 形态的轨道；方签 Tag、状态方签（ToolCall 状态、Approval / QuestionFlow 结果）与 Alert 提示条`,"--xh-shape-surface":`4px · 成面的静态容器：Card、Panel、列表容器、Tabs segment 的轨道、选择卡片、分页的描边方块`,"--xh-shape-overlay":`4px · 脱离文档流的浮层：Popover、Menu、Dialog、Notification 卡片预设、Drawer 朝向页面的两个角；引用 surface，只改承载面圆角时浮层跟着走；Notification 轻提示预设取 control`,"--xh-shape-circle":`50% · 宽高相等的圆：头像、单选圈、开关与滑杆的拇指、步骤圆点、加载环、悬浮单图标动作`,"--xh-shape-pill":`9999px · 只两类身份：状态 chip（Badge；Tag 与结果标记是方签，取 control）与一维对象（轨道、进度条、指示条、手柄、滚动条滑块）`}}),c[3]||=t(`<p>强制规则：</p><ul><li>普通 control 2px、surface 4px、overlay 4px；组件不写 6px、10px 这类独立圆角。</li><li>pill 只给明确的胶囊身份；普通按钮、字段、卡片与浮层不用 pill。Tag 与结果标记是方签，取 control。</li><li>正方盒（inline-size 与 block-size 同槽）必须取 circle，不得用 pill 冒充圆。</li><li>内层圆角不超过外层圆角减去内边距（surface 4px 的轨道留 2px 内距，里面的滑块取 2px）；相连控件（InputGroup、ButtonGroup）消除相接侧圆角。</li><li>锚定浮层里的列表行（Menu 族、Select、Combobox、TreeSelect、Mention、Cascader 列）与 Command、Transfer 的列表行是通栏行，不取圆角，悬停与选中的面铺满整行；Listbox、Tree 的行仍按 inset 内缩。</li><li>贴边铺满的通栏（Alert <code>banner</code>）不取圆角：它的边就是页面或容器的边。贴边面板（Drawer）贴住视口的两个角不取圆角，朝向页面的两个角取 overlay，与别的浮层同一把尺。</li><li>亮色、暗色与紧凑密度不改变形状身份。</li><li>PromptInput 是登记过的例外：对话输入条允许 <code>--xh-shape-surface</code>。</li></ul><h2 id="描边宽度" tabindex="-1">描边宽度 <a class="header-anchor" href="#描边宽度" aria-label="Permalink to “描边宽度”">​</a></h2>`,3),o(p,{names:[`--xh-stroke-thin`,`--xh-stroke-thick`,`--xh-stroke-strong`],notes:{"--xh-stroke-thin":`一切描边与分隔线`,"--xh-stroke-thick":`焦点环、选中指示条、滑杆拇指描边`,"--xh-stroke-strong":`只给刻意登记的粗把手（图片裁切框、可调尺寸的拖柄）`}}),c[4]||=t(`<p>焦点环一律 <code>--xh-ring-width</code>（= thick，2px）+ <code>--xh-ring-offset</code>（画在盒内一圈，不改布局盒），环色 <code>--xh-ring-focus</code> 不随语气；实心面上的环取 <code>currentColor</code>。字段外壳聚焦不画环，焦点由描边换色与底色差标出（见下文「字段外壳」）。</p><h2 id="边界三选一" tabindex="-1">边界三选一 <a class="header-anchor" href="#边界三选一" aria-label="Permalink to “边界三选一”">​</a></h2><p>任何根面 / 主面只能取下表之一，阴影与淡底都不作为边界：</p><table tabindex="0"><thead><tr><th>形态</th><th>variant</th><th>描边</th><th>底</th><th>影</th></tr></thead><tbody><tr><td>描边</td><td><code>outline</code>（缺省）</td><td><code>--xh-stroke-thin solid --xh-border-default</code>；字段与控件盒用 <code>--xh-border-control</code>（缺省档与 default 同色）</td><td><code>--xh-bg-surface</code>；字段外壳与 SignaturePad 画布铺 <code>--xh-bg-field</code>，FileUpload 拖放区铺 <code>--xh-bg-subtle</code>，勾选方框与单选圈 <code>transparent</code>，露出宿主的面</td><td>none（Card 加 <code>--xh-elevation-raised</code>，缺省 none）</td></tr><tr><td>淡底</td><td><code>subtle</code></td><td><code>--xh-stroke-thin solid transparent</code>（占位边，尺寸不跳）</td><td><code>--xh-bg-subtle</code>（有语气时 <code>--xh-tone-subtle</code>）</td><td>none</td></tr><tr><td>无壳</td><td><code>ghost</code></td><td>不写</td><td>不写</td><td>不写；只允许分隔线</td></tr></tbody></table><ul><li>有框 / 无框只走 <code>variant</code> 这一条轴：<code>outline | subtle | ghost</code>，可按下的表面多一档 <code>solid</code>。不存在 <code>bordered</code>、<code>borderless</code>、<code>plain | surface</code> 这类私有轴。</li><li><code>--xh-border-subtle</code> / <code>--xh-border-strong</code> 不得出现在根面 <code>border</code> 简写里，只能作 <code>border-block-start</code> 类分隔线与 <code>::after</code> 分隔伪元素。</li><li>raised 面（Card、Tabs segment 的滑块）必带 <code>--xh-border-default</code> 描边，影只是加成：<code>--xh-elevation-raised</code> 缺省 none，主题要抬起感时再给它一层影；只有可交互时允许 hover 抬升。</li></ul><h2 id="字段外壳-淡底、聚焦换白底" tabindex="-1">字段外壳：淡底、聚焦换白底 <a class="header-anchor" href="#字段外壳-淡底、聚焦换白底" aria-label="Permalink to “字段外壳：淡底、聚焦换白底”">​</a></h2><p>字段外壳（输入框壳、InputGroup 组壳、ColorPicker 控件、SignaturePad 画布）静息是描边形态，但铺一层淡底：</p><ul><li>静息 <code>--xh-bg-field</code>（淡底兑一半）+ <code>--xh-border-control</code> + <code>--xh-shape-control</code> + 无影。描边缺省档与浮层面板、卡片的 <code>--xh-border-default</code> 同色，页面里只有一种边线重量；<code>prefers-contrast: more</code> 才换到 3:1 的档。</li><li>hover 底不变，描边升 <code>--xh-border-strong</code>。</li><li>focus-within 换成承载面 <code>--xh-bg-surface</code> + <code>--xh-border-control-focus</code>，不画聚焦环：焦点由描边换色与底色差标出，强制色档补一圈 Highlight 环。</li><li>invalid 换 <code>--xh-border-invalid</code> 并铺 4% 失效色淡底，聚焦时让位给聚焦态。</li><li>readOnly 只填 <code>--xh-bg-subtle</code> 不动描边；disabled = <code>--xh-border-default</code> + <code>--xh-bg-subtle</code> + <code>--xh-fg-disabled</code>，不靠 opacity。</li><li>字段的 <code>subtle</code> / <code>ghost</code> 只限有壳容器内（InputGroup、Command 面板、Toolbar）使用，hover / focus 必须浮出 <code>--xh-border-control</code>。</li><li>登记过的例外：面板内嵌搜索（Command、Cascader、TreeSelect、Transfer、SideNav）不画字段外壳，只画一道 <code>border-block-end</code> 下划线，聚焦不画环、下划线也不换色；SignaturePad 不投影字段配方而自绘外壳，值必须与字段规则一致。</li></ul><p>需要白底的宿主写对应组件的底色槽，如 <code>--xh-text-field-control-bg: var(--xh-bg-surface)</code>。</p><h2 id="其余控件盒" tabindex="-1">其余控件盒 <a class="header-anchor" href="#其余控件盒" aria-label="Permalink to “其余控件盒”">​</a></h2><p>字段外壳之外带边框的控件盒：</p><ul><li>FileUpload 拖放区是一块可放置的面：静息铺 <code>--xh-bg-subtle</code> 淡底、画 1px <code>--xh-border-control</code> 虚线；悬停描边升 <code>--xh-border-strong</code>、淡底升一档，拖入换品牌描边，底仍是中性淡底一档。</li><li>Checkbox / CheckboxGroup / Transfer / Table 的方框与 RadioGroup / QuestionFlow 的圆圈是 16px 的小盒，透明底、描边重一档取 <code>--xh-border-strong</code>，一眼认得出；悬停升 <code>--xh-border-control-hover</code>。</li><li><code>--xh-bg-canvas</code> 保留给自动填充遮罩、色块选中环等必须不透明的地方，不作控件盒的底。</li></ul><h2 id="选中与当前态的标记" tabindex="-1">选中与当前态的标记 <a class="header-anchor" href="#选中与当前态的标记" aria-label="Permalink to “选中与当前态的标记”">​</a></h2><p>按语义分类，每类只允许一种标记（门禁 <code>check-selection-marker</code> 逐成员核）：</p><table tabindex="0"><thead><tr><th>语义</th><th>对象</th><th>唯一标记</th></tr></thead><tbody><tr><td>对号集合的选中</td><td>Select、Combobox、TreeSelect、Cascader、时间列、Mention、Tree、Listbox、TagGroup</td><td>透明底 + 行尾对号（<code>--xh-fg-brand</code>），正文颜色保持 rest，字重升到 medium；树的分支行也放对号，半选画横杠；TagGroup 保持标签自身的面，只多一枚文字后的对号</td></tr><tr><td>页内持久集合的选中</td><td>Table row、Transfer、GridList、SideNav 当前项、选择卡片</td><td><code>--xh-bg-brand-subtle</code> 行面 + <code>--xh-fg-on-brand-subtle</code>；Table row / Transfer / GridList 另有行首勾选框。SideNav 当前项是行面与字色，字重提到 semibold、行取 surface 圆角，不画指示条</td></tr><tr><td>导航当前页</td><td>Tabs line、Anchor、NavigationMenu、Breadcrumb</td><td>透明面 + 2px 指示条 + <code>--xh-fg-brand</code> + medium；Breadcrumb 当前页不可点、无指示条</td></tr><tr><td>格状当前</td><td>Steps indicator、Calendar 选中格</td><td>实心 <code>--xh-bg-brand</code> + <code>--xh-fg-on-brand</code>，不加粗</td></tr><tr><td>分页当前页</td><td>Pagination item</td><td>品牌描边 + <code>--xh-bg-brand-subtle</code> + <code>--xh-fg-on-brand-subtle</code>，不加粗（字重一变页码就变宽）</td></tr><tr><td>开关型（有滑块）</td><td>Tabs segment</td><td>轨道 <code>--xh-bg-subtle</code> 内的白色抬起 indicator</td></tr><tr><td>分段选中</td><td>单选组 segmented 形态</td><td>字段同款轨道（<code>--xh-bg-field</code> + <code>--xh-border-control</code>）内的品牌淡底滑块 <code>--xh-bg-segment-selected</code>，字 <code>--xh-fg-segment-selected</code> + medium</td></tr><tr><td>开关型（无滑块）</td><td>Toggle、ToggleGroup item、Toolbar <code>aria-pressed</code></td><td><code>--xh-bg-brand-subtle</code> + <code>--xh-fg-on-brand-subtle</code></td></tr><tr><td>展开路径 / 打开中（不是选中）</td><td>Menu / Menubar / NavigationMenu trigger、Cascader in-path、Date / Time trigger</td><td>与所在家族 hover 同档的中性面，不用品牌色</td></tr></tbody></table><p>选中对号一律落在行尾，不放行首：行首一格归前导图标、展开箭头、拖拽把手与勾选框。</p><p><code>--xh-bg-brand-subtle</code> 专属&quot;选中 / 当前&quot;：Calendar 的今天改成 inset 1px <code>--xh-fg-brand</code> 环 + 品牌字。Steps 已完成是唯一的例外，取品牌淡底 + 品牌对号（走过的步与当前步同属一段已点亮的进度）；点状形态的圆点不盛内容，三态由形状区分：没走到的空心圈、走过的实心标记色、当前步实心品牌并放大一档。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to “相关”">​</a></h2><ul><li><a href="/design/colors">色彩</a> · <a href="/design/shadow">阴影与材质</a></li><li>指南：<a href="/guide/theme#形状阶梯">设计令牌与主题 · 形状阶梯</a></li></ul>`,19)])}var d=i(l,[[`render`,u]]);export{c as __pageData,d as default};